INSERT INTO public.decision (meeting_type, meeting_number, point, number, contentnl, contenten) VALUES ('BV', 1, 1, 1, 'Timon de Teststudent wordt per 1 januari 2000 geïnstalleerd als Voorzitter der s.v. GEWIS.', 'Timon de Teststudent is installed as Chair of s.v. GEWIS effective from 1 January 2000.');
INSERT INTO public.decision (meeting_type, meeting_number, point, number, contentnl, contenten) VALUES ('BV', 2, 1, 1, 'Commissie Attention Test Committee met afkorting ATT wordt opgericht.', 'Committee Attention Test Committee with abbreviation ATT is established.');
INSERT INTO public.decision (meeting_type, meeting_number, point, number, contentnl, contenten) VALUES ('BV', 2, 2, 1, 'Het commissiereglement van ATT door Olaf OrdinaryActive, versie 1.0 van 17 augustus 2023 wordt goedgekeurd.', 'The committee regulations of ATT by Olaf OrdinaryActive, version 1.0 dated 17 August 2023 are approved.');
INSERT INTO public.decision (meeting_type, meeting_number, point, number, contentnl, contenten) VALUES ('BV', 2, 3, 1, 'Olaf OrdinaryActive wordt geïnstalleerd als Lid van ATT. Olaf OrdinaryActive wordt geïnstalleerd als Voorzitter van ATT.', 'Olaf OrdinaryActive is installed as Member of ATT. Olaf OrdinaryActive is installed as Chair of ATT.');
INSERT INTO public.decision (meeting_type, meeting_number, point, number, contentnl, contenten) VALUES ('BV', 2, 4, 1, 'Ellen ExternalActive wordt geïnstalleerd als Lid van ATT.', 'Ellen ExternalActive is installed as Member of ATT.');
INSERT INTO public.decision (meeting_type, meeting_number, point, number, contentnl, contenten) VALUES ('BV', 2, 5, 1, 'Gerda GraduateActive wordt geïnstalleerd als Inactief Lid van ATT.', 'Gerda GraduateActive is installed as Inactive Member of ATT.');
INSERT INTO public.decision (meeting_type, meeting_number, point, number, contentnl, contenten) VALUES ('BV', 2, 6, 1, 'Marit Misclassified wordt geïnstalleerd als Lid van ATT.', 'Marit Misclassified is installed as Member of ATT.');
INSERT INTO public.decision (meeting_type, meeting_number, point, number, contentnl, contenten) VALUES ('BV', 3, 1, 1, 'Marit Misclassified wordt gedechargeerd als Lid van ATT.', 'Marit Misclassified is discharged as Member of ATT.');
